const grid=document.querySelector('#project-grid');
function renderProjects(filter='all'){const shown=projects.filter(p=>filter==='all'||p.categories.includes(filter));grid.innerHTML=shown.map(p=>`<button class="project-card" data-project="${p.id}" aria-label="Lihat detail ${p.title}"><div class="project-image"><img src="assets/${p.image}" alt="Tampilan proyek ${p.title}" loading="lazy"><span class="arrow">↗</span></div><div class="project-meta"><span>${p.type}</span><span>DETAIL PROYEK ↗</span></div><h3>${p.title}</h3><p>${p.subtitle}</p></button>`).join('');document.querySelector('#project-count').textContent=`Menampilkan ${shown.length} proyek`}
renderProjects();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects(b.dataset.filter)}));
const dialog=document.querySelector('#project-dialog');let lastCard;
grid.addEventListener('click',e=>{const card=e.target.closest('[data-project]');if(!card)return;lastCard=card;const p=projects.find(x=>x.id===card.dataset.project);document.querySelector('#dialog-content').innerHTML=`<span class="dialog-tag">${p.type}</span><h2 id="dialog-title">${p.title}</h2><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><img class="dialog-image" src="assets/${p.image}" alt="Dokumentasi ${p.title}"><p>${p.description}</p><h3>Peran & proses</h3><p>${p.role}</p><h3>Fokus pengembangan</h3><ul>${p.features.map(t=>`<li>${t}</li>`).join('')}</ul>${p.extra?`<img class="dialog-image" src="assets/${p.extra}" alt="Peta sebaran dan filter observasi iHoya">`:''}${p.link?`<a class="button primary" href="${p.link}" target="_blank" rel="noopener">Baca publikasi ↗</a>`:''}`;dialog.showModal();dialog.scrollTop=0});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>lastCard?.focus());
const experiences={professional:[['Februari – Juli 2026','Asisten Laboratorium Machine Learning','ITENAS Bandung','Membimbing praktikum pengolahan data, visualisasi, preprocessing, dan penerapan algoritma machine learning menggunakan Python. Mendampingi pengembangan proyek serta evaluasi model.'],['Februari – Juli 2026','Asisten Laboratorium Game Programming','ITENAS Bandung','Membimbing pengembangan game menggunakan Unity dan C#: scripting, fisika, animasi, antarmuka, debugging, serta implementasi untuk PC dan WebGL.'],['Oktober 2025 – Januari 2026','Asisten Laboratorium Multimedia Engineering','ITENAS Bandung','Membimbing praktikum multimedia interaktif dan produksi konten digital menggunakan Adobe Animate, termasuk skenario sinkron, asinkron, dan hibrida.'],['Juli – Agustus 2025','Web Developer Intern','Badan Riset dan Inovasi Nasional (BRIN)','Mengembangkan SIG interaktif menggunakan Laravel, Leaflet, dan GeoJSON untuk memvisualisasikan zona sesar aktif. Mengembangkan fitur artikel ilmiah, berita, galeri, dan informasi sekolah terdekat berdasarkan lokasi geografis.']],organization:[['Januari – Desember 2025','Kepala Divisi Kewirausahaan','HMIF ITENAS','Memimpin perencanaan dan pelaksanaan program kewirausahaan, mengelola perencanaan keuangan dan kegiatan usaha, serta menjalin kerja sama dengan mitra eksternal.'],['Juli – Desember 2024','Staff Divisi Hubungan Masyarakat','HMIF ITENAS','Membangun komunikasi dengan pihak eksternal, mendukung publikasi kegiatan dan pencapaian, serta berkolaborasi dalam kegiatan sosial dan pengembangan kemitraan.'],['Agustus 2023 – Juni 2024','Staff Divisi Rumah Tangga','HMIF ITENAS','Mengelola inventaris, pencatatan peminjaman dan pengembalian barang, memantau kondisi aset, serta mengatur distribusi fasilitas organisasi.']]};
function renderExperience(tab){document.querySelector('#timeline').innerHTML=experiences[tab].map((x,i)=>`<details class="timeline-item" ${i===0?'open':''}><summary><span class="date">${x[0]}</span><div class="role"><h3>${x[1]}</h3><span class="place">${x[2]}</span></div><span class="plus" aria-hidden="true">+</span></summary><div class="details">${x[3]}</div></details>`).join('')};renderExperience('professional');
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderExperience(b.dataset.tab)}));
document.querySelector('#menu').addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}));
